"""EN 16931 / Peppol BIS 3 business-term catalogue (generated by tools/build_bt_catalog.py)."""
from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache

from ..resources import data_path

# Corrections where the shared UBL element hides the real EN 16931 cardinality:
#  BG-23 sits under an optional TaxTotal wrapper but BR-CO-18 requires at least one VAT breakdown;
#  BT-111 shares cbc:TaxAmount with BT-110 but is only required with BT-6 (BR-53);
#  BT-18 shares cbc:ID with BT-122 but is optional.
MIN_OVERRIDES = {"BG-23": 1, "BT-111": 0, "BT-18": 0}
# Allowances and charges share one UBL element, so the generated catalogue gives charge reason codes the allowance
# code list; charges use UNCL7161 (EN 16931 BT-105 / BT-145).
CODELIST_OVERRIDES = {"BT-105": "UNCL7161", "BT-145": "UNCL7161"}


@dataclass
class Term:
    id: str
    name: str
    kind: str
    parent: str | None
    min: int
    max: str
    xpath: str
    datatype: str | None
    codelist: str | None
    rules: list
    default: str | None


class Catalog:
    def __init__(self, terms: list[dict]):
        self.terms: dict[str, Term] = {}
        for t in terms:
            t = dict(t)
            t["min"] = MIN_OVERRIDES.get(t["id"], t["min"])
            t["codelist"] = CODELIST_OVERRIDES.get(t["id"], t["codelist"])
            self.terms[t["id"]] = Term(**t)
        self.order = [t["id"] for t in terms]

    def __contains__(self, item):
        return item in self.terms

    def get(self, tid: str) -> Term | None:
        return self.terms.get(tid)

    def ancestors(self, tid: str) -> list[str]:
        out, cur = [], self.terms.get(tid)
        while cur and cur.parent:
            out.append(cur.parent)
            cur = self.terms.get(cur.parent)
        return out

    def descendants(self, gid: str) -> list[str]:
        return [t for t in self.order if gid in self.ancestors(t)]

    def sort_key(self, tid: str) -> int:
        try:
            return self.order.index(tid)
        except ValueError:
            return 10_000


@lru_cache(maxsize=1)
def catalog() -> Catalog:
    data = json.loads(data_path("peppol", "bt_catalog.json").read_text(encoding="utf-8"))
    return Catalog(data["terms"])


@lru_cache(maxsize=1)
def codelists() -> dict:
    return json.loads(data_path("peppol", "codelists.json").read_text(encoding="utf-8"))
